function lesson(n,part){if(!studyAccess())return;const l=byTopic(n);if(!l)return map();const ch=chapterList(l),i=Math.max(0,Math.min(ch.length-1,Number.isInteger(part)?part:state.reads[n]||0)),c=ch[i];state.reads[n]=i;save();let body='',panel=null;if(c.kind==='base')body=`<p class="lead">${rich(l.intro)}</p>${l.blocks.map(([h,p])=>`<section><h2>${E(h)}</h2><p>${rich(p)}</p></section>`).join('')}`;if(c.kind==='deep'){panel=CoursePanels.get(n,c.blockIndex,state.draft?.tasks[state.draft.index]);const original=`<p>${rich(c.paragraphs[0])}</p>`+(panel?.html||'')+c.paragraphs.slice(1).map(p=>`<p>${rich(p)}</p>`).join('');body=c.blockIndex===0&&window.Textbook?Textbook.render(n)+`<details class="originalNotes"><summary>Краткая памятка к этой главе</summary>${original}</details>`:original;}if(c.kind==='lab')body=`<p>Сначала сформулируйте предположение, затем измените параметры. Точное вычисление и графическое наблюдение — разные способы проверки.</p><label for="inlineModelSelect">Выбрать модель<select id="inlineModelSelect"></select></label><div id="inlineLab"></div><div class="notice">Исследование не засчитывается как самостоятельное решение. После него выполните задачу без подсказки.</div>`;if(c.kind==='examples')body=`${l.examples.map(([q,s],j)=>`<section class="card"><h2>Разбор ${j+1}</h2><p>${rich(q)}</p><details><summary>Показать ход решения</summary>${rich(s)}</details></section>`).join('')}<div class="notice"><strong>Если трудно начать</strong><p>${rich(l.tip)}</p></div><h2>Проверьте понимание</h2><p>${rich(l.check[0])}</p><details><summary>Сравнить рассуждение</summary><p>${rich(l.check[1])}</p></details>${button('Проверить понятие самостоятельно','concept:'+n,'secondary')}`;if(c.kind==='summary')body=`<h2>Формулы и условия</h2>${l.formulas.map(f=>`<div class="formula">${rich('$'+f+'$')}</div>`).join('')}<ul>${l.cheat.map(x=>`<li>${rich(x)}</li>`).join('')}</ul><div class="notice"><strong>Проверьте ограничения</strong><p>${rich(l.error)}</p></div><div class="row">${button('Новые задачи','train:'+n)}${button('Проверить понимание','concept:'+n,'secondary')}${button('Базовые упражнения','fixed:'+n,'secondary')}</div>`;
shell(`<div class="reader"><aside class="readerNav"><a class="textlink" href="#map">← Все темы</a><p class="eyebrow">Тема ${n}</p><h2>${E(l.title)}</h2><ol>${ch.map((c,j)=>`<li><a class="${i===j?'selected':''}" href="#topic/${n}/${j}">${E(c.title)}</a></li>`).join('')}</ol><div class="row">${button(state.stars.includes(n)?'В избранном':'Сохранить тему','star:'+n,'secondary')}${button('Печать всей темы','printTopic:'+n,'quiet')}</div></aside><article class="readerText"><div class="readingModeSwitch"><a href="#map">← Все темы</a><a href="#read/${n}">Читать тему целиком</a></div>${state.draft?`<div class="studyContext"><a href="#session">← Вернуться к текущей задаче</a><p>Объяснение открыто: текущий ответ будет учтён как решение с поддержкой.</p><details><summary>Какой вопрос разбираем</summary><p>${rich(taskQuestion(state.draft.tasks[state.draft.index]))}</p></details></div>`:''}<div class="eyebrow">${E(l.section)} · глава ${i+1}/${ch.length}</div><h1>${E(c.title)}</h1><details class="mobileContents"><summary>Содержание темы</summary><ol>${ch.map((c,j)=>`<li><a href="#topic/${n}/${j}">${E(c.title)}</a></li>`).join('')}</ol></details>${body}${c.kind==='summary'&&l.sources?.length?`<section><h2>Задания из экзаменационного банка</h2><p>Откройте конкретные задания «Решу ЕГЭ» для дополнительной практики. Ответы на внешнем сайте не меняют прогресс здесь.</p><div class="row">${l.sources.filter(id=>/^\d+$/.test(id)).map(id=>`<a class="button secondary" href="https://mathb-ege.sdamgia.ru/problem?id=${id}" target="_blank" rel="noopener">Задание № ${id}</a>`).join('')}</div></section>`:''}<div class="readerBottom row between">${i?link('← Предыдущая глава',`topic/${n}/${i-1}`,'secondary'):'<span></span>'}${i<ch.length-1?link('Следующая глава →',`topic/${n}/${i+1}`):button('Перейти к практике','train:'+n)}</div><div class="prerequisites"><h3>Связанные основы</h3>${(pre[n]||[]).map(k=>`<a href="#topic/${k}">${E(byTopic(k).title)}</a>`).join(' · ')||'Эта тема вводит исходные понятия.'}</div></article></div>`);window.Textbook?.mount($('#app'));if(panel?.live){let values=n===3&&c.blockIndex===1?[5,6,3,8]:undefined,mode=n===3&&c.blockIndex===1?"subtract":undefined;let taskContext=false;const task=state.draft?.tasks[state.draft.index];if(panel.live==='fractionOps'&&task?.topic===n){const m=task.q.match(/(\d+)\/(\d+)\s*([+−:·])\s*(\d+)\/(\d+)/);if(m){values=[Number(m[1]),Number(m[2]),Number(m[4]),Number(m[5])];mode={'+':'add','−':'subtract',':':'divide','·':'multiply'}[m[3]];taskContext=true}}V.mount($('#chapterModel'),panel.live,{compact:true,topic:n,values,mode,context:taskContext,onTask:t=>start('lab',t)})}if(c.kind==='lab'){const primary=COURSE[n].lab||V.defaultLab[n],extra={10:['reader'],12:['powers'],14:['reader'],15:['families'],18:['powers'],19:['waves'],21:['families','rational'],22:['systems','families','rational'],23:['expLog','waves','trig'],24:['reader'],31:['reader'],37:['triangle','area'],41:['box','units'],42:['pyramid','box'],43:['solids','box'],44:['water','box']}[n]||[],models=[...new Set([primary,...extra])];$('#inlineModelSelect').innerHTML=models.map(k=>`<option value="${k}">${E(V.names[k])}</option>`).join('');V.mount($('#inlineLab'),primary,{topic:n,onTask:t=>start('lab',t)});$('#inlineModelSelect').onchange=e=>V.mount($('#inlineLab'),e.target.value,{topic:n,onTask:t=>start('lab',t)})}}
function practice(){shell(`<div class="eyebrow">Самостоятельная работа</div><h1>Практика по задаче</h1><div class="grid"><section class="card"><h2>По теме</h2><label for="trainTopic">Тема</label><select id="trainTopic">${LESSONS.map(l=>`<option value="${l.n}">${l.n}. ${E(l.title)}</option>`).join('')}</select><p>${button('Новые задания','selectedTrain')}</p>${button('Исходные упражнения','selectedFixed','secondary')}<p class="muted">Новые задания строятся из проверяемых семейств. Исходные упражнения включают открытые формы с самопроверкой.</p></section><section class="card"><h2>Короткий подход</h2><p>Пять заданий по основам. Без таймера, с вводом ответа или выбором варианта.</p>${button('Начать','quick')}<p>${button('Отложенное повторение','review','secondary')}</p></section><section class="card"><h2>Смешанная практика</h2><p>Задачи из разных разделов помогают самостоятельно выбирать способ.</p>${button('10 задач','mixed')}<p>${link('Разобрать ошибки','errors','secondary')}</p></section></div><h2>Избранное</h2><div class="topiclist">${LESSONS.filter(l=>state.stars.includes(l.n)).map(card).join('')||'<p class="muted">Темы можно сохранить в учебнике.</p>'}</div>${state.draft?link('Продолжить сохранённую работу','session'):''}`)}
function level(){shell(`<div class="narrow"><div class="eyebrow">Диагностика</div><h1>Проверить текущий уровень</h1><p class="lead">Краткий тест помогает выбрать начало. Полную картину дают проверки разделов и самостоятельные работы.</p><div class="card"><h2>Основы: 12 заданий</h2><p>Счёт, дроби, проценты, уравнения, графики, данные и геометрия. Проверка ориентировочная, все навыки курса не охватывает.</p>${button('Начать','diagnostic')}</div><div class="card"><h2>Раздел целиком</h2><label for="diagSection">Выберите раздел</label><select id="diagSection">${[...new Set(LESSONS.map(l=>l.section))].map(s=>`<option>${E(s)}</option>`).join('')}</select><p>${button('Проверить раздел','sectionDiagnostic')}</p><p class="muted">В каждой теме вопрос на понятие и новое задание; затем можно отдельно проверить слабые семейства.</p></div>${state.assessment?`<div class="notice">Последняя краткая проверка: ${state.assessment.score}/${state.assessment.total||12} самостоятельно · ${new Date(state.assessment.at).toLocaleDateString('ru-RU')}</div>`:''}</div>`)}
function conceptTask(n){const [q,original,solution]=CONCEPTS[n],offset=n%3,options=[...original.slice(offset),...original.slice(0,offset)],index=options.indexOf(original[0]);return {id:'k:'+n,topic:n,family:'concept',q,options,type:'choice',answer:String(index+1),solution}}
function distinctTask(t,tasks=[]){const seen=new Set([t.q,...tasks.map(x=>x.q)]);for(const variant of [t.variant||0,1-(t.variant||0)])for(let i=0;i<64;i++){const next=M.generate(t.topic,variant,seed());if(!seen.has(next.q))return {...next,scaffolded:true}}return null}
function seed(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]}
function start(mode,n){if(state.draft&&start.pending!==true){start.pending={mode,n};showModal(`<h2>Есть незавершённая работа</h2><p>Можно продолжить её или заменить новой. Уже записанные попытки сохранятся. Незавершённый вариант не попадёт в отчёт завершённых работ.</p><div class="row">${button('Продолжить','resume')}${button('Заменить и начать','replaceDraft','secondary')}</div>`);return}start.pending=null;let topics=[],tasks=[];if(mode==='lab')tasks=[n];else if(mode==='concept')tasks=[conceptTask(n)];else if(mode==='fixed')tasks=fixed.filter(t=>t.topic===n);else if(mode==='topic'){for(let i=0;i<8;i++){let t;for(let tries=0;tries<128;tries++){t=M.generate(n,tries<64?i%2:1-i%2,seed());if(!tasks.some(x=>x.q===t.q))break}tasks.push(t)}}else if(mode==='diagnostic'){topics=[1,3,5,7,8,14,15,21,26,27,36,41]}else if(mode==='section'){topics=LESSONS.filter(l=>l.section===n).map(l=>l.n)}else if(mode==='review'){topics=due().slice(0,5).map(l=>l.n);if(!topics.length)return toast('Темы ещё не подошли к повторению. Выберите свободную практику.')}else if(mode==='quick'){topics=Array.from({length:5},()=>[1,3,5,6,7,8,14,21,26,27][Math.floor(Math.random()*10)])}else if(mode==='mixed'){topics=Array.from({length:10},()=>1+Math.floor(Math.random()*45))}else if(mode==='exam'){tasks=M.exam(seed())}else if(mode==='custom'){tasks=state.custom.map(t=>({...t}))}else if(mode==='errors'){const last=new Map;state.attempts.forEach(a=>last.set(a.task,a));const bad=[...last.values()].filter(a=>!a.ok||a.help).slice(-10);tasks=bad.map(a=>restoreTask(a)).filter(Boolean);if(!tasks.length)return toast('Пока нет ошибок для повторной проверки.')}if(topics.length)tasks=mode==='section'?topics.flatMap((t,i)=>[conceptTask(t),M.generate(t,i%2,seed())]):topics.map((t,i)=>mode==='diagnostic'&&i%4===0?conceptTask(t):M.generate(t,i%2,seed()));if(!tasks.length)return toast('Нет подходящих задач.');state.draft={id:uid(),mode,tasks,answers:tasks.map(()=>''),results:tasks.map(()=>null),index:0,started:now(),help:tasks.map(()=>0),revealed:tasks.map(()=>false),choices:tasks.map(()=>null),tries:tasks.map(()=>0)};save();location.hash='#session';renderSession()}
function restoreTask(a){if(a.taskSnapshot)return a.taskSnapshot;if(a.task.startsWith('g:')){const parts=a.task.split(':');if(parts.length===5){const engine=parts[1]===M.VERSION?M:parts[1]==='2.1'?window.MathCourseV21:null;if(engine)return engine.generate(Number(parts[2]),Number(parts[3]),Number(parts[4]))}return null}return fixed.find(t=>t.id===a.task)||state.custom.find(t=>t.id===a.task)||state.exams.flatMap(e=>e.tasks).find(t=>t.id===a.task)}
function record(t,answer,ok,help,d,index,reason='',finalize=true){if(d.results[index])return;state.attempts.push({id:uid(),task:t.id,topic:t.topic,family:t.family||'custom',ok,help,at:now(),answer,reason,session:d.id,taskSnapshot:t});if(finalize)d.results[index]={ok,help};save()}
function choices(t){if(t.options)return t.options;const a=M.parse(t.answer);if(!a)return null;const c=[],add=r=>{if(!r||c.some(z=>M.equal(M.parse(z),r)))return;const text=a[1]!==1n?r[0]+'/'+r[1]:String(r[0]);c.push(text)};add(a);if(a[1]!==1n){for(const r of [M.rat(a[0]+1n,a[1]),M.rat(a[0]-1n,a[1]),M.rat(a[0],a[1]+1n),M.rat(a[0]+2n,a[1]+2n),M.rat(a[0]+2n,a[1])]){if(t.topic===27&&(r[0]<0n||r[0]>r[1]))continue;add(r);if(c.length===4)break}}else for(const delta of [1n,-1n,2n,3n]){add(M.rat(a[0]+delta,1));if(c.length===4)break}if(c.length!==4)return null;for(let i=c.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[c[i],c[j]]=[c[j],c[i]]}return c}
function taskQuestion(t){if(t.q==='Сравните −5² и (−5)². Запишите оба значения.')return 'Вычислите −5² и (−5)². Запишите значения в том же порядке.';if(t.q==='У той же пирамиды найдите высоту и объём.')return 'У правильной четырёхугольной пирамиды сторона основания 8, апофема 5. Найдите высоту и объём.';if(t.family==='model:numberline'){const m=t.q.match(/^Число (.+) изменили на (.+)\. Найдите результат\.$/);if(m&&M.parse(m[1])&&M.parse(m[2]))return `Вычислите: ${m[1]} + (${m[2]}).`}return TaskSupport.question(t)}
function taskIllustration(t){const q=TaskSupport.question(t);if(q==='По графику функции y = x² − 4 найдите промежуток, где y < 0, и наименьшее значение на [−3;3].')return V.plot([{fn:x=>x*x-4,label:'y = x² − 4'}],{xmin:-3,xmax:3,ymin:-5,ymax:6});return V.taskVisual(t.visual)}
function renderSession(){const d=state.draft;if(!d)return practice();if(d.mode==='exam'&&now()-d.started>=180*60000)return submitExam();const i=d.index,t=d.tasks[i],r=d.results[i],exam=d.mode==='exam',visual=taskIllustration(t),short=d.mode==='quick'||t.type==='choice',hint=d.help?.[i]||0;if(!d.tries)d.tries=d.tasks.map(()=>0);if(!d.choices)d.choices=d.tasks.map(()=>null);if(short&&!d.choices[i])d.choices[i]=choices(t);const opts=d.choices[i],guide=exam?{inputmode:'decimal',placeholder:'Целое число или конечная десятичная дробь',note:'В экзаменационном режиме записывайте только число: без единиц, обыкновенных дробей и вычислений.',symbols:['−',',']}:M.answerGuide(t),formatNote=guide.note;let controls=short&&opts&&!r?`<div class="choices">${opts.map((s,j)=>button(E(s),'choose:'+j,'secondary')).join('')}</div>`:`<form id="answerForm"><label for="answer">${guide.kind==='digits'?'Любой подходящий пример':t.type==='matching'?'Последовательность цифр':'Ответ'}</label><input id="answer" autocomplete="off" ${formatNote?'aria-describedby="answerFormat"':''} inputmode="${guide.inputmode}" value="${E(d.answers[i]||'')}" ${r?'disabled':''} placeholder="${E(guide.placeholder)}">${formatNote?`<p id="answerFormat" class="muted">${E(formatNote)}</p>`:''}<div class="keypad">${guide.symbols.map(s=>button(s,'key:'+s,'secondary')).join('')}</div>${!exam&&!r?'<button type="submit">Проверить</button>':''}</form>`;
shell(`<article class="narrow"><div class="row between"><a class="textlink" href="#practice">Сохранить и выйти</a><span>${exam?'<span id="examClock" role="timer"></span>':`${i+1} / ${d.tasks.length}`}</span></div><div class="track"><i style="width:${100*(i+1)/d.tasks.length}%"></i></div><p class="eyebrow">${exam?'Позиция '+t.position+' · '+E(t.positionTitle):E(byTopic(t.topic).title)}</p><section class="card"><div class="tasktext">${rich(taskQuestion(t))}</div>${visual}${controls}${exam?'<p class="muted">Формат экзамена: целое число или конечная десятичная дробь. Без единиц, знака % и обыкновенных дробей; десятичные запятая и точка принимаются.</p>':''}<div id="feedback">${r?feedback(t,r):d.tries[i]?retryMessage(t,d.tries[i]):''}</div>${!exam&&!r?`<div class="row">${hint<TaskSupport.steps(t).length?button(!hint?'Подсказка':TaskSupport.steps(t)[hint].title.includes('разбора')?'Начало разбора':'Следующий шаг','hint','quiet'):''}${button('Открыть разбор','reveal','quiet')}${button('Не помню','dontKnow','quiet')}</div><div id="hint">${hint&&!d.tries[i]?hintText(t,hint):''}</div>`:''}</section><div class="row between">${i?button('← Назад','prev','secondary'):'<span></span>'}${i<d.tasks.length-1?button(exam?'Далее →':r?'Следующая задача →':'Пропустить →','next','secondary'):button(exam?'Завершить работу':'Закончить подход',exam?'examConfirm':'finish','secondary')}</div>${exam?`<div class="questionNav">${d.tasks.map((_,j)=>button(String(j+1),'jump:'+j,d.answers[j]?'answered':'secondary')).join('')}</div><p class="muted">Ответы сохраняются при вводе. Время продолжает идти при закрытии страницы. Проверка и решения — после завершения. Подготовительная модель; число семейств ограничено.</p>`:'<p class="muted">Открытый разбор и самопроверка записываются как работа с помощью.</p>'}</article>`);if((r&&!r.ok)||(!r&&d.tries[i]))$('#reason')?.addEventListener('change',e=>{const a=[...state.attempts].reverse().find(a=>a.session===d.id&&a.task===t.id);if(a)a.reason=e.target.value;save()});const input=$('#answer');if(input)input.oninput=()=>{d.answers[i]=input.value;save()};$('#answerForm')?.addEventListener('submit',e=>{e.preventDefault();if(!exam)grade()});if(exam){const tick=()=>{const remain=Math.max(0,180*60-Math.floor((now()-d.started)/1000));if(!remain){submitExam();return}const el=$('#examClock');if(el)el.textContent=`${Math.floor(remain/60)}:${String(remain%60).padStart(2,'0')}`};tick();clock=setInterval(tick,1000)}}
function taskAdvice(t){return TaskSupport.steps(t)[0].text}
function hintText(t,step){const steps=TaskSupport.steps(t),i=Math.min(Math.max(1,step),steps.length)-1;return `<div class="notice"><strong>${E(steps[i].title)} · ${i+1}/${steps.length}</strong><p>${rich(steps[i].text)}</p></div>`}
function remediation(t){if(t.topic===3)return 2;if(t.topic===7)return t.variant===1?3:2;return 0}
function retryMessage(t,tries){const steps=TaskSupport.steps(t),i=Math.min(Math.max(Math.min(tries-1,1),(state.draft?.help?.[state.draft.index]||1)-1),steps.length-1),step=steps[i];return `<div class="retryNotice"><strong>✕ Пока неверно. Ответ можно исправить.</strong><p class="muted">${E(step.title)}</p><p>${rich(step.text)}</p><p>Попытка сохранена. Следующее решение этой задачи отметим как выполненное с поддержкой.</p><a href="#topic/${t.topic}/${remediation(t)}">Открыть объяснение темы</a><label>Что вызвало трудность?<select id="reason"><option>Не определено</option><option>Не понял условие</option><option>Не вспомнил правило</option><option>Вычислительная ошибка</option><option>Единицы или формат ответа</option></select></label></div>`}
function feedback(t,r){const noAnswer=r.outcome==='unknown'||(!r.ok&&!state.draft?.answers?.[state.draft.index]?.trim());return `<div class="feedback ${r.ok?'correct':'incorrect'}"><strong>${noAnswer?'Разберём решение вместе':r.ok?'✓ Ответ верный':'✕ Ответ пока неверный'}</strong>${r.help?'<p class="muted">Решено с подсказкой или после сверки с разбором.</p>':''}<p>${rich(TaskSupport.solution(t))}</p><p><strong>Ответ: ${rich(t.type==='choice'?t.options[Number(t.answer)-1]:t.answer)}</strong></p>${(!r.ok||r.help)&&!r.followup?`<div class="row">${button('Закрепить на похожей задаче','analogue','secondary')}<a href="#topic/${t.topic}/${remediation(t)}">Вернуться к объяснению</a></div>`:''}${!r.ok?`<label>Что вызвало трудность?<select id="reason"><option value="">Не определено</option><option>Не понял условие</option><option>Не выбрал модель</option><option>Не вспомнил правило</option><option>Вычислительная ошибка</option><option>Единицы или округление</option><option>Ограничения или формат ответа</option></select></label><p><a href="#topic/${t.topic}">Перейти к объяснению темы</a></p>`:''}</div>`}
function grade(forced=null,outcome=null){const d=state.draft;if(!d||d.mode==='exam'||d.results[d.index])return;const i=d.index,t=d.tasks[i];const result=forced===null?M.check(t,d.answers[i]||''):{ok:forced};if(result.ok===null){$('#feedback').innerHTML=`<div class="formatNotice" role="status"><strong>Уточним запись ответа</strong><p>${E(result.message)}</p><p>Математическая ошибка не засчитана. Можно исправить запись и проверить снова.</p></div>`;return}const helped=!!t.assistedModel||!!t.scaffolded||(d.help?.[i]||0)>0||!!d.revealed?.[i]||forced!==null;if(result.ok===false&&forced===null){d.tries[i]++;record(t,d.answers[i]||'',false,helped,d,i,'',false);d.help[i]=Math.max(1,d.help[i]||0);save();renderSession();$('#feedback')?.scrollIntoView?.({block:'start'});return}record(t,d.answers[i]||'',result.ok,helped,d,i);if(outcome){d.results[i].outcome=outcome;save()}if(state.settings.support)toast(result.ok?'Результат получен. Продолжайте в удобном темпе.':'Вернитесь к шагу, который вызвал трудность.');renderSession();$('#feedback')?.scrollIntoView?.({block:'start'});$('#reason')?.addEventListener('change',e=>{const a=[...state.attempts].reverse().find(a=>a.session===d.id&&a.task===t.id);if(a)a.reason=e.target.value;save()})}
function finish(){const d=state.draft;if(!d)return;const results=d.results.map((r,i)=>r||(d.tries?.[i]?{ok:false,help:true}:null)),ok=results.filter(x=>x?.ok&&!x.help).length,weak=[...new Set(d.tasks.filter((_,i)=>!results[i]?.ok||results[i]?.help).map(t=>t.topic))];if(d.mode==='diagnostic'||d.mode==='section')state.assessment={at:now(),score:ok,total:d.tasks.length};state.lastResult={at:now(),ok,total:results.length,help:results.filter(x=>x?.ok&&x.help).length,wrong:results.filter(x=>x&&!x.ok).length,skip:results.filter(x=>!x).length,weak};state.draft=null;save();location.hash='#result';resultPage()}
function resultPage(){const r=state.lastResult;if(!r)return home();shell(`<div class="narrow"><div class="eyebrow">Результат подхода</div><h1>Решено ${r.total-r.wrong-r.skip} из ${r.total}</h1><p>Этот результат относится к данным заданиям, а не ко всему курсу или будущей экзаменационной оценке.</p><div class="card"><p>Самостоятельно: ${r.ok}. С помощью: ${r.help}. Пока не решено: ${r.wrong}. Пропущено: ${r.skip}.</p>${r.help?'<p>Разобраться с поддержкой — полезный шаг. После перерыва проверьте этот способ на новой задаче без подсказки.</p>':''}${link('Карта знаний','map')}</div>${r.weak.length?'<h2>Рекомендуется закрепить</h2><div class="topiclist">'+r.weak.map(n=>card(byTopic(n))).join('')+'</div>':''}${link('Вернуться к занятиям','home','secondary')}</div>`)}

function examPage(){const recent=state.exams.slice(-5);shell(`<div class="eyebrow">Самостоятельные работы</div><h1>Экзаменационная тренировка</h1><p class="lead">21 позиция · 180 минут · краткие ответы. Подсказки и промежуточная проверка отключены.</p><div class="notice"><strong>Граница модели</strong><p>Это авторские тренировочные работы, построенные по карте позиций базового экзамена. В каждой позиции пока ограниченный набор семейств. Они не заменяют работу с официальной демоверсией и открытым банком и не гарантируют итоговую оценку.</p><a href="https://fipi.ru/ege/demoversii-specifikacii-kodifikatory" target="_blank" rel="noopener">Документы ФИПИ</a> · <a href="https://mathb-ege.sdamgia.ru/prob_catalog" target="_blank" rel="noopener">Каталог «Решу ЕГЭ»</a></div><div class="row">${button('Начать новую работу','exam')}${state.draft?.mode==='exam'?link('Продолжить','session','secondary'):''}${button('Подборка для печати','printExam','secondary')}</div><h2>Последние работы</h2>${recent.length?`<div class="card"><table><tr><th>Дата</th><th>Верно</th><th>Время</th><th>Разбор</th></tr>${recent.map(e=>`<tr><td>${new Date(e.at).toLocaleDateString('ru-RU')}</td><td>${e.score}/21</td><td>${Math.round((e.duration||0)/60000)} мин</td><td><a href="#examReport/${E(e.id)}">Открыть</a></td></tr>`).join('')}</table><p>Диапазон результатов: ${Math.min(...recent.map(e=>e.score))}–${Math.max(...recent.map(e=>e.score))}. Завершено работ: ${state.exams.length}. Сам факт пяти прохождений не подтверждает готовность всех навыков.</p></div>`:'<p>Завершённых работ пока нет.</p>'}<details><summary>Карта покрытия работ</summary><table><tr><th>Позиция</th><th>Умение</th><th>Тема</th></tr>${M.POSITIONS.map(p=>`<tr><td>${p.n}</td><td>${E(p.title)}</td><td><a href="#topic/${p.topic}">${p.topic}</a></td></tr>`).join('')}</table></details>`)}
function examCheck(t,s){return /^[-−]?\d+(?:[.,]\d+)?$/.test(String(s).trim())&&M.check(t,s).ok===true}
function submitExam(){const d=state.draft;if(!d||d.mode!=='exam')return;const results=d.tasks.map((t,i)=>examCheck(t,d.answers[i]||''));d.tasks.forEach((t,i)=>record(t,d.answers[i]||'',results[i],false,d,i));const report={id:d.id,at:now(),started:d.started,duration:Math.min(180*60000,now()-d.started),tasks:d.tasks,answers:d.answers,score:results.filter(Boolean).length};state.exams.push(report);state.draft=null;save();$('#modal').open&&$('#modal').close();location.hash='#examReport/'+report.id;examReport(report.id)}
function examReport(id){if(!studyAccess())return;const e=state.exams.find(e=>e.id===id);if(!e)return examPage();const weak=[...new Set(e.tasks.filter((t,i)=>!examCheck(t,e.answers[i]||'')).map(t=>t.topic))];shell(`<div class="narrow"><a href="#exam" class="textlink">← Все работы</a><h1>${e.score} из 21</h1><p>Дата: ${new Date(e.at).toLocaleString('ru-RU')}. Время: ${Math.round((e.duration||0)/60000)} мин. Оценка по школьной шкале автоматически не назначается.</p>${weak.length?`<section class="notice"><h2>Следующий шаг</h2><p>Вернитесь к смыслу ошибочных решений, затем повторите задачи без подсказок.</p><div class="row">${link('Работа над ошибками','errors')}${weak.map(n=>link(byTopic(n).title,'topic/'+n,'secondary')).join('')}</div></section>`:'<p>В этом варианте ошибок нет. Следующая полезная проверка — новая работа после перерыва.</p>'}${button('Печатать разбор','print','secondary')}${e.tasks.map((t,i)=>{const ok=examCheck(t,e.answers[i]||'');return `<section class="card"><span class="tag ${ok?'good':'attention'}">Позиция ${i+1} · ${ok?'верно':'проверить'}</span><p>${rich(taskQuestion(t))}</p>${V.taskVisual(t.visual)}<p>Ваш ответ: ${E(e.answers[i]||'пропуск')}</p><details><summary>Разбор и правильный ответ</summary><p>${rich(t.solution)}</p><p>Ответ: ${rich(t.answer)}</p><a href="#topic/${t.topic}">Повторить тему</a></details></section>`}).join('')}</div>`)}
function labs(){if(!studyAccess())return;shell(`<div class="eyebrow">Наглядные модели</div><h1>Лаборатории курса</h1><p class="lead">Выберите зависимость, сформулируйте предположение и измените параметры. Масштабы, ограничения и пояснения находятся рядом с моделью.</p><label for="labSelect">Модель</label><select id="labSelect">${Object.entries(V.names).map(([k,v])=>`<option value="${k}">${E(v)}</option>`).join('')}</select><div id="labHost" class="card" style="margin-top:20px"></div>`);$('#labSelect').value='derivative';V.mount($('#labHost'),'derivative',{onTask:t=>start('lab',t)});$('#labSelect').onchange=e=>V.mount($('#labHost'),e.target.value,{onTask:t=>start('lab',t)})}
function errors(){const last=new Map;state.attempts.forEach(a=>last.set(a.task,a));const bad=[...last.values()].filter(a=>!a.ok||a.help).sort((a,b)=>b.at-a.at);shell(`<div class="eyebrow">Работа над ошибками</div><h1>Что требует внимания</h1><p>Показаны последние результаты для каждой задачи. Успешное самостоятельное повторение убирает её из этого списка.</p>${button('Повторить до 10 задач','errors')}<div class="topiclist">${[...new Set(bad.map(a=>a.topic))].map(n=>card(byTopic(n))).join('')}</div>${bad.slice(0,40).map(a=>`<div class="card"><h3>${E(byTopic(a.topic).title)}</h3><p>${E(a.reason||'Причина не отмечена')} · ${a.help?'использована помощь':'неверный ответ'}</p><div class="row">${button('Повторить','retry:'+E(a.task),'secondary')}${link('Изучить тему','topic/'+a.topic,'secondary')}</div></div>`).join('')||'<p>Незавершённые навыки появятся после практики.</p>'}`)}
function readTopic(n){if(!studyAccess())return;const l=byTopic(n),t=window.Textbook?.topics[n];if(!l||!t)return map();const contents=t.sections.map(([h],i)=>`<li><a href="#read/${n}" data-book-jump="book-${n}-${i}">${E(h)}</a></li>`).join('')+`<li><a href="#read/${n}" data-book-jump="read-example-${n}">Разобранный пример</a></li><li><a href="#read/${n}" data-book-jump="read-reference-${n}">Все правила и дополнительные примеры</a></li>`;shell(`<div class="reader bookReader"><aside class="readerNav"><a href="#map">← Все темы</a><h2>${E(l.title)}</h2><ol>${contents}</ol><a class="button secondary" href="#topic/${n}/0">Читать по главам</a></aside><article class="readerText"><div class="readingModeSwitch"><a href="#map">← Все темы</a><a href="#topic/${n}/0">По главам</a></div><p class="eyebrow">${E(l.section)}</p><h1>${E(l.title)}</h1><details class="mobileContents"><summary>Содержание темы</summary><ol>${contents}</ol></details>${Textbook.render(n)}<section id="read-reference-${n}" class="bookReference"><h2>Все правила и дополнительные случаи</h2>${l.blocks.map(([h,p])=>`<section><h3>${E(h)}</h3><p>${rich(p)}</p></section>`).join('')}<h2>Ещё разобранные примеры</h2>${l.examples.map(([q,a])=>`<section><h3>${rich(q)}</h3><p>${rich(a)}</p></section>`).join('')}<details><summary>Дополнительные главы исходного курса</summary>${COURSE[n].blocks.map(b=>`<section><h3>${E(b.title)}</h3>${b.paragraphs.map(p=>`<p>${rich(p)}</p>`).join('')}</section>`).join('')}</details><h2>Формулы для повторения</h2>${l.formulas.map(f=>`<div class="formula">${rich('$'+f+'$')}</div>`).join('')}</section><div class="readerBottom row">${button('Потренироваться по теме','train:'+n)}${button('Упражнения учебника','fixed:'+n,'secondary')}${button('Распечатать тему','printTopic:'+n,'quiet')}</div><p><a href="#map">← Вернуться к темам</a></p></article></div>`);Textbook.mount($('#app'))}
function reference(){if(!studyAccess())return;shell(`<div class="eyebrow">Справочник</div><h1>Формулы и условия</h1><label for="formulaSearch">Найти тему или правило</label><input type="search" id="formulaSearch" placeholder="Корень, площадь, логарифм…"><div id="formulas"></div>`);const draw=()=>{const q=$('#formulaSearch').value.toLowerCase();$('#formulas').innerHTML=LESSONS.filter(l=>(l.title+' '+l.cheat.join(' ')).toLowerCase().includes(q)).map(l=>`<section class="card"><h2><a href="#topic/${l.n}">${l.n}. ${E(l.title)}</a></h2>${l.formulas.map(f=>`<div class="formula">${rich('$'+f+'$')}</div>`).join('')}<ul>${l.cheat.map(s=>`<li>${rich(s)}</li>`).join('')}</ul><p class="muted">${rich(l.error)}</p></section>`).join('')};$('#formulaSearch').oninput=draw;draw()}
function custom(){shell(`<div class="narrow"><div class="eyebrow">Мои подборки</div><h1>Собственные задания</h1><p>Локальный конструктор. Числовые ответы и дроби проверяются точно; открытое рассуждение остаётся самопроверкой.</p><form id="customForm" class="card"><label>Тема<select name="topic">${LESSONS.map(l=>`<option value="${l.n}">${l.n}. ${E(l.title)}</option>`).join('')}</select></label><label>Условие<textarea name="q" required maxlength="4000"></textarea></label><label>Правильный ответ<input name="answer" required maxlength="200"></label><label>Ход решения<textarea name="solution" required maxlength="8000"></textarea></label><button>Проверить и сохранить</button><div id="customPreview"></div></form><div class="row">${button('Решать подборку','customTrain','secondary')}${button('Печатать подборку','printCustom','secondary')}</div><p>Заданий: ${state.custom.length}. Они входят в резервную копию.</p>${state.custom.map(t=>`<div class="card"><h3>${E(byTopic(t.topic).title)}</h3><p>${rich(taskQuestion(t))}</p><details><summary>Ответ и решение</summary><p>${rich(t.answer)}</p><p>${rich(t.solution)}</p></details></div>`).join('')}</div>`);$('#customForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),t={id:'c:'+uid(),topic:Number(f.get('topic')),family:'custom',q:String(f.get('q')).trim(),answer:String(f.get('answer')).trim(),solution:String(f.get('solution')).trim()};if(!validTask(t))return toast('Проверьте поля задания.');const check=M.check(t,t.answer);if(check.ok!==true&&check.ok!==null)return toast('Ответ не проходит проверку.');state.custom.push(t);save();custom();toast(check.ok===true?'Задание сохранено. Самопроверка ответа пройдена.':'Задание сохранено с открытой формой проверки.') }}
function showModal(html){$('#dialogBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function masteryInfo(){showModal(`<h2>Что означает «закреплено»</h2><p>В текущей версии требуется самостоятельно ответить на вопрос о смысле понятия, пройти 7 исходных упражнений темы и не менее 8 разных новых заданий по двум доступным семействам, самостоятельная практика в 3 разные даты и не менее 7 верных из последних 8 самостоятельных попыток, при наличии минимум 6 попыток и отложенной встречи спустя сутки.</p><p>Это рабочий критерий по имеющемуся набору семейств, а не доказательство освоения каждого возможного задания темы. Исходные упражнения проверяют разные действия темы; новые задачи и отложенное повторение дополняют их. Самопроверка не закрывает контрольный рубеж.</p><p>Полоса отражает выполнение этих условий, а не вероятность сдачи экзамена.</p>`)}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return(h>>>0).toString(16)}
const b64=b=>{let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
async function pack(s){let bytes=new TextEncoder().encode(JSON.stringify(s)),kind='J';if(typeof CompressionStream!=='undefined'){bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new CompressionStream('deflate'))).arrayBuffer());kind='Z'}const body=b64(bytes);return 'PN2'+kind+'.'+body+'.'+hash(body)}
async function unpack(code){if(typeof code!=='string'||code.length>8000000)throw Error('Неподдерживаемый объём кода');if(code.startsWith('PN1.')){const [v,b,c]=code.split('.');if(hash(b).padStart(8,'0')!==c)throw Error('Повреждён код');const raw=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(b.replace(/-/g,'+').replace(/_/g,'/')),x=>x.charCodeAt(0))));return migrate(Array.isArray(raw)?{v:1,attempts:raw[2].map(a=>({t:a[0],i:a[1],ok:!!(a[2]&1),help:!!(a[2]&2),at:raw[1]+a[3]})),stars:raw[3],assessment:raw[4]}:raw)}const [v,b,c,...extra]=code.trim().split('.');if(code.length>8000000||!['PN2J','PN2Z'].includes(v)||!b||extra.length||hash(b)!==c)throw Error('Код неполный, повреждён или имеет другую версию.');let bytes=Uint8Array.from(atob(b.replace(/-/g,'+').replace(/_/g,'/')),x=>x.charCodeAt(0));if(v==='PN2Z'){if(typeof DecompressionStream==='undefined')throw Error('Этот браузер не поддерживает сжатый код. Используйте файл JSON.');const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate')).getReader(),chunks=[];let total=0;while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>10000000){reader.cancel();throw Error('Слишком большой объём данных.')}chunks.push(value)}bytes=new Uint8Array(total);let at=0;for(const c of chunks){bytes.set(c,at);at+=c.length}}const s=JSON.parse(new TextDecoder().decode(bytes));if(!valid(s))throw Error('Данные сохранения не прошли проверку структуры.');return s}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
let importCandidate=null;
async function progress(){showModal(`<h2>Прогресс и настройки</h2><div class="tabs">${button('Данные и перенос','progressData','secondary')}${button('Настройки чтения','settings','secondary')}</div><p>Попыток: ${state.attempts.length}. Работ: ${state.exams.length}. Создаётся полный код сохранения…</p>`);const code=await pack(state);if(!$('#modal').open)return;$('#dialogBody').innerHTML=`<h2>Прогресс и перенос</h2><div class="row">${button('Настройки чтения','settings','secondary')}${button('Скачать резервную копию','download','secondary')}</div><p>Попыток: ${state.attempts.length}. Работ: ${state.exams.length}. Код включает историю, избранное, свои задания и незавершённую работу.</p><label for="exportCode">Код переноса<textarea id="exportCode" class="code" readonly></textarea></label>${button('Скопировать','copy','secondary')}<div id="qr"></div><p class="muted">Код сжат и проверяется на случайное повреждение, но не зашифрован. Получатель кода может прочитать данные. При большой истории используйте файл; данные для QR не обрезаются.</p><details><summary>Восстановить или объединить</summary><label>Код<textarea id="importCode" class="code"></textarea></label>${button('Проверить код','inspectImport','secondary')}<label>Или файл<input id="importFile" type="file" accept="application/json,.json"></label><div id="importPreview"></div></details>`;$('#exportCode').value=code;const qrText=location.protocol==='https:'?location.href.split('#')[0]+'#restore/'+code:code;if(qrText.length<1500){try{const q=qrcode(0,'M');q.addData(qrText);q.make();$('#qr').innerHTML='<div class="qr">'+q.createSvgTag({scalable:true,margin:4})+'</div><p class="muted">'+(location.protocol==='https:'?'Сканирование открывает предпросмотр восстановления.':'В локальном просмотре QR содержит текст кода; на HTTPS-сайте — ссылку.')+'</p>'}catch{$('#qr').textContent='Для этого сохранения используйте полный код или файл.'}}else $('#qr').textContent='Сохранение слишком велико для удобного QR. Полный код и файл содержат все данные.';$('#importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('Файл слишком большой.');const raw=JSON.parse(await f.text()),s=raw.version===2?raw:migrate(raw);if(!valid(s))throw Error('Некорректное сохранение');inspectImport(s)}catch(e){toast(e.message)}}}
function inspectImport(s){importCandidate=s;$('#importPreview').innerHTML=`<div class="notice"><h3>Данные проверены</h3><p>${s.attempts.length} попыток, ${s.exams.length} работ, ${s.custom.length} своих задач. Сейчас на устройстве ${state.attempts.length} попыток.</p><p>Перед изменением будет предложено скачать текущую копию. При объединении настройки и незавершённая работа текущего устройства сохраняются, если уже существуют.</p><div class="row">${button('Объединить','mergeImport')}${button('Заменить','replaceImport','secondary')}</div></div>`}
function settings(){showModal(`<h2>Настройки чтения</h2><label>Размер текста<select id="fontSize"><option value="1">Обычный</option><option value="1.1">Увеличенный</option><option value="1.2">Крупный</option></select></label><label class="inline"><input type="checkbox" id="motionPref"> Короткие переходы между экранами</label><label class="inline"><input type="checkbox" id="supportPref"> Короткие поддерживающие сообщения</label><p class="muted">Системное уменьшение движения также учитывается. Звук не используется.</p>${button('Сохранить','saveSettings')}`);$('#fontSize').value=String(state.settings.font);$('#motionPref').checked=state.settings.motion;$('#supportPref').checked=state.settings.support}
function printContent(html){const root=$('#printArea');root.innerHTML=html;window.Textbook?.mount(root);document.body.classList.add('printing');print();document.body.classList.remove('printing');root.innerHTML=''}
function printTopic(n){if(!studyAccess())return;const l=byTopic(n);printContent(`<h1>${E(l.title)}</h1>${window.Textbook?Textbook.render(n):''}<p>${rich(l.intro)}</p>${l.blocks.map(([h,t])=>`<h2>${E(h)}</h2><p>${rich(t)}</p>`).join('')}${COURSE[n].blocks.map(b=>`<h2>${E(b.title)}</h2>${b.paragraphs.map(p=>`<p>${rich(p)}</p>`).join('')}`).join('')}<h2>Примеры</h2>${l.examples.map(([q,s])=>`<p><strong>${rich(q)}</strong></p><p>${rich(s)}</p>`).join('')}${l.formulas.map(f=>`<div class="formula">${rich('$'+f+'$')}</div>`).join('')}`)}
function printTasks(tasks,title){if(!studyAccess())return;showModal(`<h2>Печать подборки</h2><p>${tasks.length} заданий. Решения можно включить отдельным разделом.</p><label class="inline"><input id="printSolutions" type="checkbox"> Добавить ответы и решения</label>${button('Открыть печать','doPrintSet')}`);printTasks.pending={tasks,title}}
function about(){shell(`<article class="narrow"><h1>О курсе и источниках</h1><p>Авторский курс для самостоятельной подготовки к базовой математике. Подробные объяснения, модели и практика не являются официальными КИМ и не гарантируют оценку.</p><p>Карта экзаменационных позиций взята за основу из доступных материалов ФИПИ-2027. Перед экзаменом необходимо сверить окончательные требования, инструкции и справочные материалы.</p><p><a href="https://fipi.ru/ege/demoversii-specifikacii-kodifikatory" rel="noopener" target="_blank">Официальные документы ФИПИ</a> · <a href="https://mathb-ege.sdamgia.ru/prob_catalog" rel="noopener" target="_blank">Каталог «Решу ЕГЭ»</a></p><h2>Как проверяются знания</h2><p>Статусы относятся к двум текущим генеративным семействам на тему, а не ко всем возможным случаям. Сложные открытые ответы исходного задачника могут требовать самопроверки. Учебные работы по 21 позиции используют ограниченный набор авторских моделей.</p><h2>Хранение</h2><p>Данные остаются в браузере. Регистрации, внешней аналитики и автоматической синхронизации нет. Делайте резервные копии: очистка данных сайта удаляет локальную историю. Код переноса не является шифрованием.</p><h2>Библиотеки</h2><p>KaTeX 0.16.22 и qrcode-generator 2.0.4 поставляются локально под лицензиями MIT. Тексты лицензий сохранены в vendor.</p></article>`)}
function route(){const [p,n,i]=location.hash.slice(1).split('/');const actions={home,map,practice,level,exam:examPage,labs,errors,reference,custom,about,result:resultPage,session:renderSession,topic:()=>lesson(Number(n),i===undefined?undefined:Number(i)),read:()=>readTopic(Number(n)),examReport:()=>examReport(n),restore:async()=>{home();await progress();try{inspectImport(await unpack(n));$('#importPreview').closest('details').open=true}catch(e){toast(e.message)}}};(actions[p]||home)()}
document.addEventListener('click',async e=>{const jump=e.target.closest('[data-book-jump]');if(jump){e.preventDefault();const contents=jump.closest('.mobileContents');if(contents)contents.open=false;document.getElementById(jump.dataset.bookJump)?.scrollIntoView({block:'start'});return}const b=e.target.closest('[data-act]');if(!b)return;const [a,...args]=b.dataset.act.split(':'),n=Number(args[0]),d=state.draft;try{
if(['quick','mixed','review','diagnostic','exam','errors'].includes(a))start(a);
if(a==='concept')start('concept',n);if(a==='train')start('topic',n);if(a==='fixed')start('fixed',n);if(a==='selectedTrain')start('topic',Number($('#trainTopic').value));if(a==='selectedFixed')start('fixed',Number($('#trainTopic').value));if(a==='sectionDiagnostic')start('section',$('#diagSection').value);if(a==='customTrain')start('custom');
if(a==='resume'){$('#modal').close();location.hash='#session';renderSession()}if(a==='replaceDraft'){const p=start.pending;state.draft=null;$('#modal').close();start.pending=true;start(p.mode,p.n)}
if(a==='star'){state.stars=state.stars.includes(n)?state.stars.filter(k=>k!==n):[...state.stars,n];save();route()}
if(a==='analogue'&&d&&d.mode!=='exam'){const i=d.index,r=d.results[i],t=d.tasks[i];if(r&&(!r.ok||r.help)&&!r.followup&&d.tasks.length<100){const next=distinctTask(t,d.tasks);if(!next)return toast('Для этой подборки новое условие не нашлось. Закрепите тему в смешанной практике позже.');r.followup=true;d.tasks.splice(i+1,0,next);for(const [key,value] of [['answers',''],['results',null],['help',0],['revealed',false],['choices',null],['tries',0]]){if(!d[key])d[key]=d.tasks.map(()=>value);else d[key].splice(i+1,0,value)}d.index++;save();renderSession()}}
if(a==='next'&&d){if(d.index<d.tasks.length-1)d.index++;save();renderSession()}if(a==='prev'&&d){d.index=Math.max(0,d.index-1);save();renderSession()}if(a==='jump'&&d){d.index=n;save();renderSession()}
if(a==='choose'&&d){d.answers[d.index]=d.tasks[d.index].type==='choice'?String(n+1):d.choices[d.index][n];grade()}if(a==='key'&&d){const input=$('#answer');if(input&&!input.disabled){const ch=args.join(':');input.value+=ch==='−'?'-':ch;d.answers[d.index]=input.value;save();input.focus()}}
if(a==='hint'&&d){d.help[d.index]=Math.min(TaskSupport.steps(d.tasks[d.index]).length,(d.help[d.index]||0)+1);save();renderSession();$(d.tries[d.index]?'#feedback':'#hint')?.scrollIntoView?.({block:'start'})}
if(a==='reveal'&&d){d.revealed[d.index]=true;save();$('#feedback').innerHTML=`<div class="feedback"><p>${rich(TaskSupport.solution(d.tasks[d.index]))}</p><p>Ответ: ${rich(d.tasks[d.index].answer)}</p></div><div class="row">${button('Решение совпало','selfYes','secondary')}${button('Нужна доработка','selfNo','secondary')}</div><p class="muted">Оба выбора отмечаются как самопроверка.</p>`}if(a==='selfYes')grade(true);if(a==='selfNo')grade(false);if(a==='dontKnow')grade(false,'unknown');
if(a==='finish')finish();if(a==='examConfirm')showModal(`<h2>Завершить работу?</h2><p>Заполнено ${d.answers.filter(x=>x.trim()).length} из 21. После завершения ответы изменить нельзя. Будет доступен разбор.</p>${button('Сдать работу','submitExam')} ${button('Вернуться','closeModal','secondary')}`);if(a==='submitExam')submitExam();if(a==='closeModal')$('#modal').close();
if(a==='retry'){const taskId=args.join(':'),attempt=[...state.attempts].reverse().find(x=>x.task===taskId),t=attempt&&restoreTask(attempt);if(t){if(state.draft)return toast('Сначала завершите или сохраните текущую работу через раздел практики.');state.draft={id:uid(),mode:'topic',tasks:[t],answers:[''],results:[null],index:0,started:now(),help:[0],revealed:[false],choices:[null],tries:[0]};save();location.hash='#session';renderSession()}else toast('Исходная задача этой версии не сохранилась. Откройте тему и выполните новое задание.')}
if(a==='masteryInfo')masteryInfo();if(a==='progressData')progress();if(a==='settings')settings();if(a==='saveSettings'){state.settings={font:Number($('#fontSize').value),support:$('#supportPref').checked,motion:$('#motionPref').checked};save();prefs();$('#modal').close()}
if(a==='downloadRecovery'&&recoveryRaw!==null)download('mathematics-original-recovery.txt',recoveryRaw,'text/plain');if(a==='download')download('mathematics-progress-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state));if(a==='copy'){try{await navigator.clipboard.writeText($('#exportCode').value);toast('Код скопирован')}catch{$('#exportCode').select();toast('Скопируйте выделенный код вручную.')}}if(a==='inspectImport')inspectImport(await unpack($('#importCode').value));
if((a==='mergeImport'||a==='replaceImport')&&importCandidate){if(recoveryLocked){if(!archiveUnreadable())throw Error('Исходную запись пока не удалось сохранить отдельно. Скачайте её кнопкой восстановления; перезапись заблокирована.');download('mathematics-original-recovery.txt',recoveryRaw,'text/plain')}download('progress-before-import.json',JSON.stringify(state));if(a==='replaceImport')state=importCandidate;else{const merge=(x,y)=>[...new Map([...x,...y].map(a=>[a.id,a])).values()];const candidate={...state,attempts:merge(importCandidate.attempts,state.attempts).sort((a,b)=>a.at-b.at),exams:merge(importCandidate.exams,state.exams).sort((a,b)=>a.at-b.at),custom:merge(importCandidate.custom,state.custom),stars:[...new Set([...state.stars,...importCandidate.stars])],reads:{...importCandidate.reads,...state.reads},draft:state.draft||importCandidate.draft};if(!valid(candidate))throw Error('Объединённые данные превышают поддерживаемый объём. Используйте отдельные копии.');state=candidate}importCandidate=null;recoveryLocked=false;storageWarning='';save();prefs();$('#modal').close();route();toast('Данные восстановлены. Исходная резервная запись сохранена.')}
if(a==='print')print();if(a==='printTopic')printTopic(n);if(a==='printExam')printTasks(M.exam(seed()),'Авторская тренировочная работа');if(a==='printCustom')printTasks(state.custom,'Собственная подборка');if(a==='doPrintSet'){const {tasks,title}=printTasks.pending,solutions=$('#printSolutions').checked;$('#modal').close();printContent(`<h1>${E(title)}</h1>${tasks.map((t,i)=>`<section><h2>${i+1}.</h2><p>${rich(taskQuestion(t))}</p>${taskIllustration(t)}<div class="answerLines"></div></section>`).join('')}${solutions?'<div class="pageBreak"></div><h1>Ответы и решения</h1>'+tasks.map((t,i)=>`<p><strong>${i+1}. ${rich(t.answer)}</strong></p><p>${rich(t.solution)}</p>`).join(''):''}`)}
}catch(err){toast(err.message||'Действие не удалось. Данные остаются в текущем состоянии.')}});
$('#settings').onclick=progress;$('.close').onclick=()=>$('#modal').close();window.addEventListener('hashchange',route);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});route();
function offlineSetup(){const status=$('#offlineStatus'),show=text=>{if(status)status.textContent=text};if(location.protocol==='file:'){show('Автономная папка открыта напрямую. Установка сайта доступна по HTTPS.');return}if(!('serviceWorker' in navigator)){show('Этот браузер не поддерживает сохранение сайта для работы без сети.');return}const pending=setTimeout(()=>show('Сохранение ещё не подтверждено. Перед поездкой проверьте открытие без сети.'),10000);navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('Доступна новая версия. Сохраните работу и откройте сайт снова.')})});return navigator.serviceWorker.ready}).then(()=>{clearTimeout(pending);show('Материалы сохранены для работы без сети. Данные прогресса остаются в этом браузере.')}).catch(err=>{clearTimeout(pending);show('Работа без сети не подготовлена. Попробуйте открыть сайт в Safari или Chrome по HTTPS.');console.warn('Offline preparation failed:',err)})}offlineSetup();
